CREATE PROCEDURE [dbo].[sp_CompanyDetails_Insert]
(
    @CompnyName NVARCHAR(200) = NULL,
    @Street NVARCHAR(200) = NULL,
    @StreetNo NVARCHAR(50) = NULL,
    @Block NVARCHAR(100) = NULL,
    @Building NVARCHAR(100) = NULL,
    @ZipCode NVARCHAR(20) = NULL,
    @City NVARCHAR(100) = NULL,
    @Country NVARCHAR(10) = NULL,
    @Phone1 NVARCHAR(50) = NULL,
    @Phone2 NVARCHAR(50) = NULL,
    @Fax NVARCHAR(50) = NULL,
    @E_Mail NVARCHAR(254) = NULL,
    @FreeZoneNo NVARCHAR(100) = NULL,
    @TaxIdNum NVARCHAR(100) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Check if TaxIdNum already exists
    IF EXISTS
    (
        SELECT 1
        FROM [dbo].[CompanyDetails]
        WHERE [CompnyName] = @CompnyName
    )
    BEGIN
        -- Update existing record
        UPDATE [dbo].[CompanyDetails]
        SET
            CompnyName = @CompnyName,
            Street = @Street,
            StreetNo = @StreetNo,
            Block = @Block,
            Building = @Building,
            ZipCode = @ZipCode,
            City = @City,
            Country = @Country,
            Phone1 = @Phone1,
            Phone2 = @Phone2,
            Fax = @Fax,
            E_Mail = @E_Mail,
            FreeZoneNo = @FreeZoneNo,
            UpdatedDateTime = GETDATE()
        WHERE [CompnyName] = @CompnyName;

        -- Return existing TaxIdNum
        SELECT [CompnyName]
        FROM [dbo].[CompanyDetails]
        WHERE [CompnyName] = @CompnyName;
    END
    ELSE
    BEGIN
        -- Insert new record
        INSERT INTO [dbo].[CompanyDetails]
        (
            CompnyName,
            Street,
            StreetNo,
            Block,
            Building,
            ZipCode,
            City,
            Country,
            Phone1,
            Phone2,
            Fax,
            E_Mail,
            FreeZoneNo,
            TaxIdNum,
            CreatedDateTime,
            UpdatedDateTime
        )
        VALUES
        (
            @CompnyName,
            @Street,
            @StreetNo,
            @Block,
            @Building,
            @ZipCode,
            @City,
            @Country,
            @Phone1,
            @Phone2,
            @Fax,
            @E_Mail,
            @FreeZoneNo,
            @TaxIdNum,
            GETDATE(),
            GETDATE()
        );

        -- Return newly created TaxIdNum
        SELECT @CompnyName AS CompnyName;
    END
END;
GO
