        INSERT INTO dbo.ItemMaster
        (
            ItemCode,
            ItemName,
            FrgnName,
            ItmsGrpCod,
            PrchseItem,
            SellItem,
            InvntItem,
            UgpCode,
            SalUnitMsr,
            U_VZ_SubGroup,
            U_VZ_SubGroup2,
            ManBtchNum,
            ManSerNum,
            validFor,
            validFrom,
            validTo,
            CreatedDateTime,
            UpdatedDateTime
        )
        VALUES
        (
            @ItemCode,
            @ItemName,
            @FrgnName,
            @ItmsGrpCod,
            @PrchseItem,
            @SellItem,
            @InvntItem,
            @UgpCode,
            @SalUnitMsr,
            @U_VZ_SubGroup,
            @U_VZ_SubGroup2,
