    @PrimCurr NVARCHAR(10) = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- Check if ListNum already exists
    IF EXISTS
    (
        SELECT 1
        FROM [dbo].[PriceList]
        WHERE ListNum = @ListNum
    )
    BEGIN
        -- Update existing record
        UPDATE [dbo].[PriceList]
        SET
            ListName = @ListName,
            ValidFor = @ValidFor,
            PrimCurr = @PrimCurr,
            UpdatedDateTime = GETDATE()
        WHERE ListNum = @ListNum;

        -- Return existing ListNum
        SELECT ListNum
        FROM [dbo].[PriceList]
        WHERE ListNum = @ListNum;
    END
    ELSE
    BEGIN
        -- Insert new record
        INSERT INTO [dbo].[PriceList]
        (
            ListNum,
            ListName,
            ValidFor,
            PrimCurr,
            CreatedDateTime,
            UpdatedDateTime
        )
        VALUES
        (
            @ListNum,
            @ListName,
            @ValidFor,
            @PrimCurr,
            GETDATE(),
            GETDATE()
        );

        -- Return newly created ListNum
        SELECT @ListNum AS ListNum;
    END
END; 
